// @vitest-environment node
import { readdirSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import type { Step, StepAnswer } from "../src/surveys/types";
import { canGoBack, progressOf, setAnswer, startWalk, walkAnswers, walkBack, walkEnd, walkNext, walkStep, walkTo, type Walk } from "../src/surveys/walk";

// The fixtures were generated by running the application's own
// lib/surveys/walk.ts and flow.ts over the same actions. The port must
// produce the same trace.
const dir = resolve(import.meta.dirname, "fixtures/flows");
const fixtures = readdirSync(dir)
  .filter((f) => f.endsWith(".json"))
  .map((f) => JSON.parse(readFileSync(resolve(dir, f), "utf8")) as Fixture);

type Action = { answer: StepAnswer } | "next" | "back";
interface Fixture {
  name: string;
  steps: Step[];
  actions: Action[];
  expected: { trace: Record<string, unknown>[]; end: { thanks: string | null }; answers: unknown[] };
}

const state = (steps: Step[], walk: Walk) => {
  const step = walkStep(steps, walk);
  return { step: step?.key ?? null, progress: step ? progressOf(steps, step.key) : null, canBack: canGoBack(walk), answers: walkAnswers(steps, walk) };
};

function replay({ steps, actions }: Fixture) {
  let walk = startWalk();
  const trace: Record<string, unknown>[] = [{ action: "start", ...state(steps, walk) }];
  let end: { thanks: string | null } | null = null;
  for (const action of actions) {
    if (action === "next") {
      const finished = walkEnd(steps, walk);
      if (finished) {
        end = { thanks: finished.thanks?.key ?? null };
        trace.push({ action, end, answers: walkAnswers(steps, walk) });
        continue;
      }
      const to = walkNext(steps, walk);
      if (to !== "done") walk = walkTo(walk, to);
    } else if (action === "back") {
      walk = walkBack(steps, walk);
    } else {
      walk = setAnswer(walk, walkStep(steps, walk)!.key, action.answer);
    }
    trace.push({ action, ...state(steps, walk) });
  }
  return { trace, end, answers: walkAnswers(steps, walk) };
}

describe("walk port against the application's fixtures", () => {
  it("has the fixtures the brief asks for", () => {
    expect(fixtures.map((f) => f.name).sort()).toEqual(
      expect.arrayContaining(["linear", "rating-branch-low", "rating-branch-high", "choice-branches", "optional-skipped", "back-navigation", "branch-own-thanks"]),
    );
  });

  it.each(fixtures.map((f) => [f.name, f] as const))("%s: same steps, progress, end and answers", (_, fixture) => {
    expect(replay(fixture)).toEqual(fixture.expected);
  });
});
